#!/usr/bin/env bash
# the step-6 B1 proof: pristine cache-off rebuild at the work path, R5 against the 9b3829c38 objects, the include-order record, the fan-in readings, style, the eight smokes, the gates that read the touched files
S4=/tmp/claude-1000/-home-claude-cto/b1caac4c-9b75-4393-9260-1c72f906f86b/scratchpad; SO=/tmp/claude-1000/-home-claude-cto/25cbd82c-ea4e-46bc-9ee6-3c52fc5dcc1f/scratchpad; W=$SO/hdr/SCRIP; H=$SO/hdr/harness/scripts; R=/home/claude_cto/SCRIP; cd $W || exit 2
echo "== 0 pristine  $(date +%T)"; CCACHE_DISABLE=1 S4E_NO_BUILD_CACHE=1 make -j8 pristine > $S4/b1-pristine.log 2>&1; echo "pristine rc=$? compiles=$(grep -c -- ' -c ' $S4/b1-pristine.log) errors=$(grep -c ' error' $S4/b1-pristine.log)"
echo "== 1 R5"; WO=/tmp/si_objs$(printf %s "$W" | tr / -)
bash $H/util_objects_identical_stripped.sh --no-comdat $S4/parent-objs-6b1/obj $WO $S4/parent-objs-6b1/out $W/out > $S4/r5-6b1.log 2>&1; echo "R5 rc=$? :: $(grep '^objects=' $S4/r5-6b1.log | cut -c1-300)"; grep -E '^(DIFF|ONLY)' $S4/r5-6b1.log | head -12 | cut -c1-200
echo "== 2 order"; python3 -I $S4/hdr_order.py --root $W --cmds $S4/make-n.txt --out $S4/order-child-6b1.json 2>&1 | tail -1; python3 -I $S4/order_cmp.py $S4/order-parent-6b1.json $S4/order-child-6b1.json $R/src $W/src 2>&1 | tail -4
echo "== 3 fan-in"; for h in driver/driver_globals.h driver/driver_data.h driver/driver_label.h driver/driver_call.h driver/driver_hooks.h ir/ast.h runtime/by_name_dispatch.h runtime/core/core.h; do python3 -I $H/util_header_fanin.py --root $W $h 2>/dev/null | tail -1 | cut -c1-120; done
python3 -I $H/util_header_fanin.py --root $R --unused 2>/dev/null | sort > $S4/unused-parent-6b1.txt; python3 -I $H/util_header_fanin.py --root $W --unused 2>/dev/null | sort > $S4/unused-child-6b1.txt; echo "unused: parent $(grep -vc '^summary' $S4/unused-parent-6b1.txt) child $(grep -vc '^summary' $S4/unused-child-6b1.txt)"; diff $S4/unused-parent-6b1.txt $S4/unused-child-6b1.txt | grep '^[<>]' | head -8 | cut -c1-160
python3 -I $H/util_header_fanin.py --root $R --bare 2>/dev/null | sort > $S4/bare-parent-6b1.txt; python3 -I $H/util_header_fanin.py --root $W --bare 2>/dev/null | sort > $S4/bare-child-6b1.txt; echo "bare: $(tail -1 $S4/bare-parent-6b1.txt) -> $(tail -1 $S4/bare-child-6b1.txt)"; diff $S4/bare-parent-6b1.txt $S4/bare-child-6b1.txt | grep '^[<>]' | head -6 | cut -c1-160
echo "== 4 style"; files=$(git diff --name-only HEAD -- src | while read f; do [ -f "$f" ] && echo "$f"; done; git ls-files --others --exclude-standard src); echo "$files" | tr '\n' ' ' | cut -c1-300; echo; python3 ../harness/scripts/util_reflow_200.py --check $files 2>&1 | tail -1 | cut -c1-160; python3 ../harness/scripts/strip_comments.py --check $files 2>&1 | tail -1 | cut -c1-160
echo "== 5 smokes  $(date +%T)"; for l in snobol4 snocone rebus icon prolog pascal raku scrip_all_modes; do S4E_DONE_WHEN_RUN=1 timeout -k 5 1800 bash ../harness/scripts/test_smoke_$l.sh > $S4/smoke6b1-$l.log 2>&1; echo "SMOKE $l rc=$?"; done
echo "== 6 gates  $(date +%T)"; for g in test_gate_no_header_reaches_more_units_than_its_users.sh test_gate_icn_a_closed_file_raises_212_on_read_and_213_on_write.sh test_gate_pl_stream_property_sees_the_standard_streams_before_any_file_operation.sh test_gate_every_tree_kind_has_a_dump_name.sh test_gate_pl_no_new_global.sh test_gate_stage2_isolation.sh test_gate_term_wordref_ratchet.sh test_gate_delimited_aggregate_census_ratchet.sh test_gate_no_c_to_bb_ratchet.sh test_gate_p7_prolog_setjmp_gone.sh test_gate_dyn_caps_ratchet.sh; do t0=$(date +%s); S4E_DONE_WHEN_RUN=1 timeout -k 5 1800 bash $H/$g > $S4/gate6b1-$g.log 2>&1; echo "GATE $g rc=$? $(( $(date +%s) - t0 ))s :: $(grep -E 'GATE (OK|PASS|FAIL|RED|GREEN|UNPROVEN)|⛔|REFUSE|summary' $S4/gate6b1-$g.log | tail -1 | cut -c1-110)"; done
grep -E '^  (RED|ok|FAIL) +ARM' $S4/gate6b1-test_gate_no_header_reaches_more_units_than_its_users.sh.log | cut -c1-100
echo "B1 PROOF DONE $(date +%T)"
